                        <fieldset class="workspace-fieldset"><legend>Gambar untuk tiga tempat berbeda</legend><p class="workspace-muted">JPG, PNG, atau WebP, maksimal 5 MB per file. Storefront menjadi WebP maksimal 800px; poster Telegram maksimal 1600px. Tanpa unggahan baru, gambar tersimpan tetap dipakai.</p><div class="workspace-grid workspace-media-grid">
                    @foreach(['image' => ['Kartu produk · Web Storefront', 'image_url', 'Jika kosong, memakai ikon katalog atau gambar default toko.'], 'telegram_image' => ['Detail produk · Bot Telegram', 'telegram_image_url', 'Disarankan landscape 16:9. Jika kosong, memakai gambar detail family atau teks.'], 'telegram_channel_image' => ['Poster stok · Store Channel', 'telegram_channel_image_url', 'Poster khusus pengumuman stok di channel, bukan gambar detail bot.']] as $field => [$label, $urlField, $help])
                        <label class="workspace-media">{{ $label }}<span class="workspace-muted">{{ $help }}</span><img x-show="filePreviews.{{ $field }} || workspace.product.{{ $urlField }}" x-bind:src="filePreviews.{{ $field }} || workspace.product.{{ $urlField }} || ''" alt="Pratinjau {{ $label }}"><input name="{{ $field }}" type="file" accept="image/jpeg,image/png,image/webp" x-on:change="selectFile('{{ $field }}', $event)" x-bind:aria-invalid="Boolean(error('appearance', '{{ $field }}'))" aria-describedby="workspace-error-{{ $field }}"><span id="workspace-error-{{ $field }}" class="workspace-field-error" x-text="error('appearance', '{{ $field }}')"></span></label>
                    @endforeach
                    </div></fieldset>@include('admin.products.workspace-feedback', ['formKey' => 'appearance', 'saveLabel' => 'Simpan gambar & tampilan'])</form>
                @endif
                </div>
            </section>
        @endforeach
        </div>
        <dialog x-ref="supplierDialog" class="workspace-dialog" aria-labelledby="workspace-supplier-dialog-title" x-on:cancel.prevent="closeSupplierDialog()" x-on:close="supplierDialogOpen = false">
            <div class="workspace-panel-heading"><div><h3 id="workspace-supplier-dialog-title">Tambah sumber supplier</h3><p class="workspace-muted">Pilih item katalog privat yang sesuai produk toko.</p></div><button type="button" class="workspace-button" aria-label="Tutup pemilih supplier" x-on:click="closeSupplierDialog()">Tutup</button></div>
            <label>Cari supplier atau item katalog<input type="search" x-ref="catalogSearch" x-model="catalogQuery" x-on:input.debounce.300ms="searchCatalog()" autocomplete="off"></label><p class="workspace-muted" x-show="catalogLoading" role="status">Memuat katalog supplier…</p><p class="workspace-field-error" x-show="catalogError" x-text="catalogError" role="alert"></p><button class="workspace-button" type="button" x-show="catalogError" x-on:click="searchCatalog()">Coba muat katalog lagi</button><p class="workspace-empty" x-show="!catalogLoading && !catalogError && !catalog.length">Tidak ada item yang cocok. Ubah pencarian atau sinkronkan katalog pada halaman Supplier.</p>
            <form x-on:submit.prevent="attachSupplier()">
                <fieldset class="workspace-catalog"><legend class="sr-only">Item katalog supplier</legend>
                    <template x-for="item in catalog" :key="item.id"><label class="workspace-catalog-option"><input type="radio" name="catalog_item_id" x-bind:value="item.id" x-model="catalogSelection" x-bind:disabled="item.requires_input || !item.orderable || mutationBusy()"><span><strong x-text="item.supplier.name"></strong><span x-text="item.name"></span><small class="workspace-muted workspace-wrap" x-text="'SKU ' + item.external_id + ' · ' + (item.currency || item.supplier.currency)"></small><span class="workspace-warning" x-show="item.requires_input || !item.orderable">Tidak mendukung pembelian otomatis tanpa input.</span><span class="workspace-warning" x-show="item.supplier.is_fresh === false">Data supplier kedaluwarsa.</span></span></label></template>
                </fieldset>
                <div class="workspace-actions"><button type="button" class="workspace-button" x-on:click="searchCatalog(catalogPage - 1)" x-bind:disabled="catalogLoading || catalogPage <= 1">Sebelumnya</button><span x-text="'Halaman ' + catalogPage + ' / ' + catalogLastPage"></span><button type="button" class="workspace-button" x-on:click="searchCatalog(catalogPage + 1)" x-bind:disabled="catalogLoading || catalogPage >= catalogLastPage">Berikutnya</button></div>
                <label class="workspace-checkbox"><input type="checkbox" required x-model="equivalentConfirmed"><span>Saya memastikan paket, durasi, dan garansinya sesuai produk toko.</span></label>
                <p class="workspace-field-error" role="alert" x-text="feedback.supplier"></p><ul class="workspace-field-error" role="alert"><template x-for="(message, index) in messages('supplier')" :key="index"><li x-text="message"></li></template></ul>
                <div class="workspace-save"><button class="workspace-button" type="button" x-on:click="closeSupplierDialog()" x-bind:disabled="mutationBusy()">Batal</button><button class="workspace-button workspace-primary" type="submit" x-bind:disabled="mutationBusy() || !catalogSelection || !equivalentConfirmed || catalogLoading" x-text="saving.supplier ? 'Menambahkan…' : 'Tambahkan sumber'"></button></div>
            </form>
        </dialog>
    </div>
</x-admin-dashboard.linked-shell>
</body>
</html>
